+++ b/src/main/java/com/example/customers/domain/CustomerFilter.java
@@ -0,0 +1,109 @@
+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: free text matched against names, and a
+ * set of statuses. A customer has to satisfy both halves to be shown.
+ *
+ * <p>The name is split on whitespace into terms and <em>every</em> term must
+ * appear in the first or the last name, so {@code ada aal} and {@code aal ada}
+ * both find {@code Ada Aaltonen} while {@code ada virtanen} finds nobody.
+ * Matching ignores case and accents in both directions: {@code makinen},
+ * {@code MAKINEN} and {@code mäkinen} all find {@code Mäkinen}.
+ *
+ * <p>An empty name matches every customer, and an empty status set matches every
+ * status.
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        EnumSet<CustomerStatus> selected = EnumSet.noneOf(CustomerStatus.class);
+        if (statuses != null) {
+            selected.addAll(statuses);
+        }
+        // An EnumSet iterates in declaration order, which is the order the
+        // statuses are written to the URL in.
+        statuses = Collections.unmodifiableSet(selected);
+    }
+
+    /** A filter for a name only. */
+    public static CustomerFilter byName(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    /** A filter for statuses only. */
+    public static CustomerFilter byStatus(CustomerStatus... statuses) {
+        return new CustomerFilter("", Set.of(statuses));
+    }
+
+    /** True when this filter lets every customer through. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /**
+     * The name filter split into normalised terms; empty when no name is set.
+     */
+    public List<String> nameTerms() {
+        String normalized = normalize(name);
+        return normalized.isEmpty() ? List.of() : List.of(WHITESPACE.split(normalized));
+    }
+
+    /**
+     * This filter as a predicate. The name terms are normalised once here rather
+     * than once per customer, so this is what a backend scanning a table should
+     * use.
+     */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        if (terms.isEmpty() && allowed.isEmpty()) {
+            return customer -> true;
+        }
+        return customer -> (allowed.isEmpty() || allowed.contains(customer.status()))
+                && matchesTerms(customer, terms);
+    }
+
+    /** True when the given customer passes this filter. */
+    public boolean matches(Customer customer) {
+        return toPredicate().test(customer);
+    }
+
+    private static boolean matchesTerms(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!firstName.contains(term) && !lastName.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds away case and accents, so that {@code MAKINEN} and {@code mäkinen}
+     * come out looking the same.
+     */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
